    "summary": "朝食付き12泊。観光日の専属ガイドと車両、送迎、天門山や漓江クルーズなど記載の入場券、高速鉄道2等席2区間、エコノミークラス航空便2区間を含みます。張家界では階段を多く歩くため、歩行に不安がある方は予約前にお知らせください。",
