    "hotelNote": "2名1室で朝食付き12泊。上海に最初の2泊と最後の1泊、武陵源2泊、張家界市内1泊、鳳凰2泊、桂林2泊、陽朔2泊です。4ダイヤ相当のホテルがある都市ではそれを基準とし、鳳凰では現地で評価の高い川沿いの宿を選びます。宿泊先はお支払い前に確認します。",
    "serviceNote": "各都市の観光日は現地ガイドと車両がお客様のグループ専用です。全送迎、張家界国家森林公園、百龍エレベーター、天門山ロープウェー、龍脊など記載の基本入場券、漓江クルーズと荷物の別車輸送、遇龍河の竹いかだ1回を含みます。張家界―鳳凰、鳳凰―桂林は高速鉄道2等席、上海―張家界、桂林―上海はエコノミークラス便です。ガイドは都市ごとに交代し、移動日は両都市のドライバーが送迎。観光日は英語ガイドを含みます。日本語ガイドの手配可否と料金は予約前に確認します。",
