    "bookingNote": "掲載価格は該当人数で2名1室を利用した場合の1名あたりの最低料金です。天門山と張家界国家森林公園の入場券にはコースと入場時間の指定があり、観光日の順序は券の確保結果に合わせます。列車の座席、航空便、ホテル、最終総額はお支払い前に書面で確定します。",
